package com.brasa.restaurant.controller;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.service.*;import jakarta.validation.Valid;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;@RestController@RequestMapping("/api")public class AdminController{private final AdminService s;private final DashboardService d;public AdminController(AdminService s,DashboardService d){this.s=s;this.d=d;}@GetMapping("/dashboard/resumo")public DashboardResponse dashboard(@RequestParam(defaultValue="hoje")String periodo){return d.summary(periodo);}@GetMapping("/categorias")public List<CategoriaDto>categories(){return s.categories();}@PostMapping("/categorias")public CategoriaDto createCategory(@Valid@RequestBody CategoriaDto x){return s.saveCategory(null,x);}@PutMapping("/categorias/{id}")public CategoriaDto updateCategory(@PathVariable String id,@Valid@RequestBody CategoriaDto x){return s.saveCategory(id,x);}@DeleteMapping("/categorias/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void deleteCategory(@PathVariable String id){s.deleteCategory(id);}@GetMapping("/produtos")public List<ProdutoDto>products(){return s.products();}@PostMapping("/produtos")public ProdutoDto createProduct(@Valid@RequestBody ProdutoDto x){return s.saveProduct(null,x);}@PutMapping("/produtos/{id}")public ProdutoDto updateProduct(@PathVariable String id,@Valid@RequestBody ProdutoDto x){return s.saveProduct(id,x);}@DeleteMapping("/produtos/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void deleteProduct(@PathVariable String id){s.deleteProduct(id);}@GetMapping("/pedidos")public List<PedidoResponse>orders(){return s.orders();}@PatchMapping("/pedidos/{id}/status")public PedidoResponse status(@PathVariable String id,@Valid@RequestBody StatusPedidoRequest x){return s.changeStatus(id,x.status());}@GetMapping("/funcionarios")public List<FuncionarioDto>employees(){return s.employees();}@PostMapping("/funcionarios")public FuncionarioDto employee(@Valid@RequestBody FuncionarioDto x){return s.saveEmployee(x);}@GetMapping("/escalas")public List<EscalaDto>schedules(@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate semana){return s.schedules(semana);}@PutMapping("/escalas")public List<EscalaDto>saveSchedules(@Valid@RequestBody List<EscalaDto>x){return s.saveSchedules(x);}@GetMapping("/chamados")public List<ChamadoResponse>calls(){return s.calls();}@PatchMapping("/chamados/{id}/atender")public ChamadoResponse answer(@PathVariable String id){return s.answer(id);}@PostMapping("/mesas/{numero}/fechar")@ResponseStatus(HttpStatus.NO_CONTENT)public void close(@PathVariable int numero){s.closeTable(numero);}}
